// WinBack: Covert Operations (USA) - game registration for N64ModernRuntime.
//
// Registers the recompiled code section, the ROM identity and the RSP
// microcode used for audio tasks. Graphics tasks go to RT64.

#include <cstdint>
#include <cstdio>

#include "recomp.h"
#include "funcs.h"
#include "librecomp/game.hpp"
#include "librecomp/overlays.hpp"
#include "librecomp/rsp.hpp"
#include "ultramodern/ultramodern.hpp"

#include "winback_game.hpp"
#include "debug_stats.hpp"

// Generated by RSPRecomp from the n_audio microcode (ROM 0xD9F30).
RspExitReason aspMain(uint8_t* rdram, uint32_t ucode_addr);

// N64Recomp's section table: one statically linked code section, no overlays.
#include "recomp_overlays.inl"

namespace {

constexpr uint64_t rom_hash = 0x1432B2EFE9B1573EULL;  // XXH3-64 of the USA .z64

RspUcodeFunc* get_rsp_microcode(const OSTask* task) {
    switch (task->t.type) {
        case M_AUDTASK:
            if (winback::stats::audio_tasks++ == 0) {
                std::printf("[winback] first audio task: ucode %08X size %X, data %08X size %X, data_ptr %08X size %X\n",
                    (uint32_t)task->t.ucode, task->t.ucode_size, (uint32_t)task->t.ucode_data, task->t.ucode_data_size,
                    (uint32_t)task->t.data_ptr, task->t.data_size);
            }
            return aspMain;
        default:
            std::fprintf(stderr, "[winback] unknown RSP task type %u\n", task->t.type);
            return nullptr;
    }
}

} // namespace

const recomp::rsp::callbacks_t& winback::rsp_callbacks() {
    static const recomp::rsp::callbacks_t callbacks{
        .get_rsp_microcode = get_rsp_microcode,
    };
    return callbacks;
}

bool winback::register_game() {
    recomp::overlays::overlay_section_table_data_t sections{
        .code_sections = section_table,
        .num_code_sections = num_sections,
        .total_num_sections = num_sections,
    };
    recomp::overlays::overlays_by_index_t overlays{
        .table = overlay_sections_by_index,
        .len = sizeof(overlay_sections_by_index) / sizeof(overlay_sections_by_index[0]),
    };
    recomp::overlays::register_overlays(sections, overlays);

    recomp::GameEntry entry{};
    entry.rom_hash = rom_hash;
    entry.internal_name = "WIN BACK";
    entry.display_name = "WinBack: Covert Operations";
    entry.game_id = game_id;
    entry.mod_game_id = "winback";
    entry.save_type = recomp::SaveType::None;  // Saves to the Controller Pak.
    entry.is_enabled = true;
    entry.entrypoint_address = (gpr)(int32_t)0x80025C00;
    entry.entrypoint = recomp_entrypoint;
    entry.thread_create_callback = [](uint8_t* rdram, recomp_context*) {
        winback::stats::threads_created++;
        winback::stats::register_thread(rdram, ultramodern::this_thread());
    };
    winback::stats::start();
    return recomp::register_game(entry);
}
